arguments.content:
:root {
  --bg-color: #FAFAFA;
  --text-primary: #171717;
  --text-secondary: #666666;
  --text-tertiary: #888888;
  --accent-color: #0072F5;
  --accent-hover: #005bb5;
  --border-color: #EAEAEA;
  --card-bg: #FFFFFF;
  --header-bg: rgba(255, 255, 255, 0.85);
  --shadow-sm: 0 2px 4px rgba(0,0,0,0.02);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.05);
  --shadow-lg: 0 12px 24px rgba(0,0,0,0.08);
  --border-radius-sm: 6px;
  --border-radius-md: 12px;
  --border-radius-lg: 16px;
  --transition-speed: 0.2s;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition-speed);
}

ul {
  list-style: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--border-radius-sm);
  cursor: pointer;
  transition: all var(--transition-speed);
  border: 1px solid transparent;
}

.btn-primary {
  background-color: var(--text-primary);
  color: #fff;
}

.btn-primary:hover {
  background-color: #333;
}

.btn-secondary {
  background-color: #fff;
  border-color: var(--border-color);
  color: var(--text-primary);
}

.btn-secondary:hover {
  background-color: var(--bg-color);
  border-color: #ccc;
}

.btn-ghost {
  background-color: transparent;
  color: var(--text-secondary);
}

.btn-ghost:hover {
  background-color: var(--border-color);
  color: var(--text-primary);
}

.btn-outline {
  background-color: transparent;
  border-color: rgba(255, 255, 255, 0.4);
  color: #fff;
}

.btn-outline:hover {
  background-color: rgba(255, 255, 255, 0.1);
  border-color: #fff;
}

.btn-large {
  padding: 12px 24px;
  font-size: 16px;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--header-bg);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.header-left, .header-right {
  display: flex;
  align-items: center;
  gap: 24px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.03em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link, .nav-btn {
  background: none;
  border: none;
  font-family: inherit;
  font-size: 14px;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 8px 12px;
  border-radius: var(--border-radius-sm);
  transition: all var(--transition-speed);
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-link:hover, .nav-btn:hover {
  color: var(--text-primary);
  background-color: var(--bg-color);
}

/* Dropdowns */
.nav-item {
  position: relative;
}

.dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  margin-top: 8px;
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-md);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 100;
}

.nav-item:hover .dropdown,
.nav-btn[aria-expanded="true"] + .dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

/* Mega Menu (Products) */
.mega-menu {
  width: 700px;
  padding: 24px;
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.mega-menu-column h4, .simple-menu-section h4 {
  font-size: 13px;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.mega-menu-column ul, .simple-menu-section ul {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mega-menu-column a {
  display: flex;
  flex-direction: column;
  padding: 8px;
  border-radius: var(--border-radius-sm);
  transition: background-color var(--transition-speed);
}

.mega-menu-column a:hover {
  background-color: var(--bg-color);
}

.mega-menu-column a span {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
}

.mega-menu-column a small {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 2px;
}

/* Simple Menu (Resources) */
.simple-menu {
  width: 450px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 24px;
}

.simple-menu-section a {
  display: block;
  font-size: 14px;
  color: var(--text-secondary);
  padding: 6px 8px;
  border-radius: var(--border-radius-sm);
}

.simple-menu-section a:hover {
  color: var(--text-primary);
  background-color: var(--bg-color);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: var(--text-primary);
}

/* Main Content */
main {
  padding-top: 48px;
  padding-bottom: 80px;
}

/* Featured Section */
.featured-section {
  margin-bottom: 64px;
}

.featured-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 24px;
}

.featured-card {
  display: flex;
  flex-direction: column;
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
}

.featured-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card-content {
  padding: 32px;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.large-card .card-content {
  padding: 48px;
}

.meta {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.featured-card h2 {
  font-size: 32px;
  margin-bottom: 16px;
}

.featured-card h3 {
  font-size: 24px;
  margin-bottom: 12px;
}

.featured-card p {
  color: var(--text-secondary);
  margin-bottom: 24px;
  font-size: 16px;
  flex-grow: 1;
}

.agentic-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: auto;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
}

.stat {
  display: flex;
  flex-direction: column;
}

.stat-value {
  font-size: 32px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.04em;
}

.stat-label {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.4;
  margin-top: 4px;
}

.featured-side {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Feed Section & Filters */
.filters-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 40px;
  gap: 24px;
  flex-wrap: wrap;
}

.categories {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.category-pill {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 8px 16px;
  border-radius: 99px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-speed);
}

.category-pill:hover {
  border-color: #ccc;
  color: var(--text-primary);
}

.category-pill.active {
  background-color: var(--text-primary);
  border-color: var(--text-primary);
  color: #fff;
}

.search-box {
  position: relative;
  min-width: 280px;
}

.search-box .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-tertiary);
}

.search-box input {
  width: 100%;
  padding: 10px 16px 10px 40px;
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-sm);
  font-family: inherit;
  font-size: 14px;
  outline: none;
  transition: border-color var(--transition-speed);
}

.search-box input:focus {
  border-color: var(--accent-color);
}

/* Posts Grid */
.posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.post-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
}

.post-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.post-category {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--accent-color);
  margin-bottom: 12px;
}

.post-title {
  font-size: 18px;
  margin-bottom: 12px;
  line-height: 1.4;
}

.post-excerpt {
  color: var(--text-secondary);
  font-size: 14px;
  margin-bottom: 24px;
  flex-grow: 1;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-meta {
  font-size: 13px;
  color: var(--text-tertiary);
  display: flex;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--border-color);
  padding-top: 16px;
  margin-top: auto;
}

.no-results {
  text-align: center;
  padding: 64px 0;
  color: var(--text-secondary);
}

.no-results.hidden {
  display: none;
}

.no-results i {
  font-size: 48px;
  color: var(--text-tertiary);
  margin-bottom: 16px;
}

.no-results h3 {
  color: var(--text-primary);
  margin-bottom: 8px;
}

.load-more-container {
  display: flex;
  justify-content: center;
}

.load-more-btn.hidden {
  display: none;
}

/* CTA Banner */
.cta-banner {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 24px;
  margin-top: 64px;
}

.cta-content {
  border-radius: var(--border-radius-lg);
  padding: 48px;
}

.main-cta {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
}

.main-cta h2 {
  font-size: 32px;
  margin-bottom: 16px;
}

.main-cta p {
  color: var(--text-secondary);
  font-size: 18px;
  margin-bottom: 32px;
  max-width: 500px;
}

.cta-actions {
  display: flex;
  gap: 16px;
}

.enterprise-cta {
  background-color: var(--text-primary);
  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.enterprise-cta h3 {
  font-size: 24px;
  margin-bottom: 16px;
}

.enterprise-cta p {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 32px;
  font-size: 16px;
}

/* Footer */
.site-footer {
  background-color: var(--card-bg);
  border-top: 1px solid var(--border-color);
  padding-top: 64px;
  padding-bottom: 32px;
  font-size: 14px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 64px;
}

.footer-col h4 {
  font-size: 14px;
  margin-bottom: 16px;
  color: var(--text-primary);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-col a {
  color: var(--text-secondary);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.mt-4 {
  margin-top: 32px;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--border-color);
  color: var(--text-secondary);
}

.status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.status-indicator {
  width: 10px;
  height: 10px;
  background-color: var(--accent-color);
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(0, 114, 245, 0.2);
}

.social-links {
  display: flex;
  gap: 16px;
  font-size: 20px;
}

.social-links a:hover {
  color: var(--text-primary);
}

/* Responsive */
@media (max-width: 1024px) {
  .featured-grid {
    grid-template-columns: 1fr;
  }

  .agentic-stats {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .posts-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cta-banner {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .header-inner .main-nav, .header-inner .btn-ghost {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .posts-grid {
    grid-template-columns: 1fr;
  }

  .cta-actions {
    flex-direction: column;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    align-items: flex-start;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Data
  const categories = [
    "All Posts", "Engineering", "Community", "Company News", 
    "Customers", "v0", "Security", "Changelog", "Press"
  ];

  const posts = [
    { id: 1, title: "A new programming model for durable execution", category: "Engineering", date: "Apr 16", author: "Pranav Mehta", excerpt: "The gap between prototypes and production-ready systems is huge. Code that's trivial to run locally falls apart the moment it needs to handle failures, restarts, and real traffic. Framework-defined infrastructure solved this for web applications. Workflows extends that model to long-running systems." },
    { id: 2, title: "Agentic Infrastructure", category: "Engineering", date: "Apr 9", author: "Tom Reeves", excerpt: "Every generation of software eventually demands a new generation of infrastructure. First, we configured servers by hand. Next, the cloud turned infrastructure into APIs. Then, a more important shift: infrastructure derived from the application itself. LLMs and coding agents are driving the next transition, and it's happening fast." },
    { id: 3, title: "Zero Data Retention on AI Gateway", category: "Security", date: "Apr 6", author: "Jerlyn and Dan", excerpt: "Building with multiple AI models means wrestling with fragmented data policies. With many different model providers, it..." },
    { id: 4, title: "Optimizing Sandbox snapshots", category: "Engineering", date: "Apr 2", author: "Tom, Rob, and 2 others", excerpt: "When we recently shipped filesystem snapshots in Sandbox to let teams capture and restore a sandbox..." },
    { id: 5, title: "How a startup made a blog platform work for humans and AI alike", category: "Customers", date: "Apr 1", author: "Nic Vargas", excerpt: "A two-person, YC-backed startup that built an agentic CMS for businesses..." },
    { id: 6, title: "Making build tool 96% faster with agents, sandboxes, and humans", category: "Engineering", date: "Mar 30", author: "Anthony Shew", excerpt: "Build tool is now 81–91% faster to compute the task graph in our repositories, scaling with repo size..." },
    { id: 7, title: "Unified reporting for all AI Gateway usage", category: "Company News", date: "Mar 25", author: "Jerlyn and Dan", excerpt: "If you're shipping AI features, you already have usage data. The problem is that it's across providers, keys, an..." },
    { id: 8, title: "Agent responsibly", category: "Community", date: "Mar 30", author: "Matthew Carr", excerpt: "The following is based on an internal talk given at DeployCloud. We're sharing it publicly because the problem it describes isn't unique to us, and the framework is useful for any team shipping with agents. Coding agents generate code at unprecedented speeds — but without rigorous judgment, they are a fast way to ship bad assumptions directly to production." },
  ];

  // State
  let activeCategory = "All Posts";
  let searchQuery = "";
  let visiblePostsCount = 6;

  // DOM Elements
  const filtersContainer = document.getElementById('category-filters');
  const postsGrid = document.getElementById('posts-grid');
  const searchInput = document.getElementById('search-input');
  const showMoreBtn = document.getElementById('show-more-btn');
  const noResultsMsg = document.getElementById('no-results');

  // Initialize
  function init() {
    renderFilters();
    renderPosts();
    setupEventListeners();
  }

  // Render Category Filters
  function renderFilters() {
    filtersContainer.innerHTML = categories.map(cat => `
      <button class="category-pill ${cat === activeCategory ? 'active' : ''}" data-category="${cat}">
        ${cat}
      </button>
    `).join('');
  }

  // Render Posts
  function renderPosts() {
    // Filter posts
    let filteredPosts = posts.filter(post => {
      const matchCategory = activeCategory === "All Posts" || post.category === activeCategory;
      const matchSearch = post.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          post.excerpt.toLowerCase().includes(searchQuery.toLowerCase());
      return matchCategory && matchSearch;
    });

    // Check no results
    if (filteredPosts.length === 0) {
      postsGrid.innerHTML = '';
      noResultsMsg.classList.remove('hidden');
      showMoreBtn.classList.add('hidden');
      return;
    }

    noResultsMsg.classList.add('hidden');

    // Slice for pagination
    const postsToShow = filteredPosts.slice(0, visiblePostsCount);

    // Render HTML
    postsGrid.innerHTML = postsToShow.map(post => `
      <a href="#" class="post-card">
        <div class="post-category">${post.category}</div>
        <h3 class="post-title">${post.title}</h3>
        <p class="post-excerpt">${post.excerpt}</p>
        <div class="post-meta">
          <span class="date">${post.date}</span>
          <span class="separator">·</span>
          <span class="author">${post.author}</span>
        </div>
      </a>
    `).join('');

    // Toggle Load More button
    if (filteredPosts.length > visiblePostsCount) {
      showMoreBtn.classList.remove('hidden');
    } else {
      showMoreBtn.classList.add('hidden');
    }
  }

  // Event Listeners
  function setupEventListeners() {
    // Category click
    filtersContainer.addEventListener('click', (e) => {
      if (e.target.classList.contains('category-pill')) {
        activeCategory = e.target.getAttribute('data-category');
        visiblePostsCount = 6; // Reset pagination
        renderFilters();
        renderPosts();
      }
    });

    // Search input
    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value;
      visiblePostsCount = 6; // Reset pagination
      renderPosts();
    });

    // Show more button
    showMoreBtn.addEventListener('click', () => {
      visiblePostsCount += 6;
      renderPosts();
    });

    // Mega menu toggles (for accessibility and touch devices)
    const navBtns = document.querySelectorAll('.nav-btn');
    navBtns.forEach(btn => {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        const expanded = this.getAttribute('aria-expanded') === 'true';

        // Close others
        navBtns.forEach(b => b.setAttribute('aria-expanded', 'false'));

        // Toggle current
        this.setAttribute('aria-expanded', !expanded);
      });
    });

    // Close dropdowns when clicking outside
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.has-dropdown')) {
        navBtns.forEach(b => b.setAttribute('aria-expanded', 'false'));
      }
    });
  }

  // Run
  init();
});
